insert into public.pages select * from jsonb_populate_recordset(null::public.pages, $QA$[{"id":"719a1528-3da9-4391-a7e7-afec793107da","slug":"about","title":"About Us","body":"DRAFT — sample text for review. Replace with your own story before publishing.\n\n## Our story\nWe started with a simple belief: everyday essentials should feel exceptional. Every piece in our collection is chosen for its craftsmanship, quality materials and lasting design.\n\n## What we stand for\n- Carefully curated products from trusted makers\n- Honest pricing with no hidden costs\n- Friendly, personal customer care\n\n## Our promise\nIf something is not right, our team is here to help. We want every order to be a pleasure from checkout to delivery.","seo_title":"About Us","seo_description":"Learn about our story, our values and the care we put into every order.","is_published":false,"show_in_footer":true,"sort_order":1,"created_at":"2026-10-21T13:33:34.309148+00:00","updated_at":"2026-10-21T13:33:34.309148+00:00","meta_keywords":null,"canonical_url":null,"robots_noindex":false,"og_image_url":null,"image_url":null,"image_alt":null,"is_draft_sample":true}, 
 {"id":"f887aa6d-d622-44fd-afc1-67a4a78a96da","slug":"contact","title":"Contact Us","body":"DRAFT — sample text for review.\n\nHave a question about an order, a product or a partnership? Send us a message using the form and our team will reply as soon as possible.","seo_title":"Contact Us","seo_description":"Get in touch with our customer care team about orders, products or partnerships.","is_published":false,"show_in_footer":true,"sort_order":2,"created_at":"2026-10-21T13:33:34.309148+00:00","updated_at":"2026-10-21T13:33:34.309148+00:00","meta_keywords":null,"canonical_url":null,"robots_noindex":false,"og_image_url":null,"image_url":null,"image_alt":null,"is_draft_sample":true}, 
 {"id":"72e04be2-fbab-4790-a302-446c5e7eb707","slug":"faqs","title":"FAQs","body":"DRAFT — sample text for review.\n\nFind quick answers to the most common questions about orders, shipping, payments and returns. Can't find what you need? Contact our team.","seo_title":"Frequently Asked Questions","seo_description":"Answers to common questions about orders, shipping, payments and returns.","is_published":false,"show_in_footer":true,"sort_order":3,"created_at":"2026-10-21T13:33:34.309148+00:00","updated_at":"2026-10-21T13:33:34.309148+00:00","meta_keywords":null,"canonical_url":null,"robots_noindex":false,"og_image_url":null,"image_url":null,"image_alt":null,"is_draft_sample":true}, 
 {"id":"794527b4-3528-46a0-aaf2-ce06f3b2297d","slug":"shipping-policy","title":"Shipping Policy","body":"DRAFT — sample text for review. Confirm all timelines and charges before publishing.\n\n## Processing time\nOrders are usually prepared within 1–2 business days. You will receive a tracking number once your order ships.\n\n## Delivery times\nDelivery times depend on your location and the shipping method chosen at checkout. Estimated times are shown before you place your order.\n\n## Shipping charges\nShipping costs are calculated at checkout based on your delivery address.\n\n## Cash on Delivery\nCash on Delivery is available in selected areas. Please keep the exact amount ready when your order arrives.\n\n## Questions\nIf your order is delayed, please contact us with your order number.","seo_title":"Shipping Policy","seo_description":"Processing times, delivery estimates, shipping charges and Cash on Delivery information.","is_published":false,"show_in_footer":true,"sort_order":4,"created_at":"2026-10-21T13:33:34.309148+00:00","updated_at":"2026-10-21T13:33:34.309148+00:00","meta_keywords":null,"canonical_url":null,"robots_noindex":false,"og_image_url":null,"image_url":null,"image_alt":null,"is_draft_sample":true}, 
 {"id":"4a175f6b-4657-4e50-92a1-9c78680d667a","slug":"returns-policy","title":"Return & Refund Policy","body":"DRAFT — sample text for review. Confirm the return window and conditions before publishing.\n\n## Returns\nIf you are not completely satisfied, you may request a return from your account within the return window shown on your order. Items must be unused, in original packaging and with all tags attached.\n\n## How to request a return\n1. Sign in and open your order.\n2. Choose Request a return and tell us the reason.\n3. Our team will review your request and share the next steps.\n\n## Refunds\nOnce your return is received and inspected, approved refunds are processed to the original payment method. Cash on Delivery orders are refunded by an agreed method.\n\n## Damaged or incorrect items\nPlease contact us within 48 hours of delivery with photos so we can make it right.","seo_title":"Return & Refund Policy","seo_description":"How to request a return, eligibility conditions and how refunds are processed.","is_published":false,"show_in_footer":true,"sort_order":5,"created_at":"2026-10-21T13:33:34.309148+00:00","updated_at":"2026-10-21T13:33:34.309148+00:00","meta_keywords":null,"canonical_url":null,"robots_noindex":false,"og_image_url":null,"image_url":null,"image_alt":null,"is_draft_sample":true}, 
 {"id":"b62fd88b-fc1a-4a74-a124-926d44f86921","slug":"privacy-policy","title":"Privacy Policy","body":"DRAFT — sample text for review. Have this policy checked for your country's legal requirements before publishing.\n\n## Information we collect\nWe collect the details you provide when you create an account, place an order or contact us — such as your name, email, phone number and delivery address.\n\n## How we use it\n- To process and deliver your orders\n- To respond to your questions\n- To improve our store and, with your consent, to send updates\n\n## Cookies\nWe use essential cookies to run the store and, with your consent, analytics cookies to understand how it is used.\n\n## Sharing\nWe only share your information with partners needed to fulfil your order, such as delivery companies. We never sell your personal data.\n\n## Your rights\nYou may request access to, correction of or deletion of your personal data by contacting us.","seo_title":"Privacy Policy","seo_description":"How we collect, use and protect your personal information.","is_published":false,"show_in_footer":true,"sort_order":6,"created_at":"2026-10-21T13:33:34.309148+00:00","updated_at":"2026-10-21T13:33:34.309148+00:00","meta_keywords":null,"canonical_url":null,"robots_noindex":false,"og_image_url":null,"image_url":null,"image_alt":null,"is_draft_sample":true}, 
 {"id":"47b66c26-6a65-4627-a931-6faf788a417a","slug":"terms","title":"Terms & Conditions","body":"DRAFT — sample text for review. Have these terms checked for your country's legal requirements before publishing.\n\n## Using this website\nBy using this website and placing an order you agree to these terms.\n\n## Orders and pricing\nAll orders are subject to availability and confirmation. Prices are shown in the store currency and may change without notice. We reserve the right to cancel orders affected by pricing errors.\n\n## Payment\nAvailable payment methods are shown at checkout.\n\n## Intellectual property\nAll content on this website, including images and text, belongs to us or our partners and may not be reused without permission.\n\n## Limitation of liability\nTo the extent allowed by law, we are not liable for indirect losses arising from the use of this website.\n\n## Changes\nWe may update these terms from time to time. The latest version is always published on this page.","seo_title":"Terms & Conditions","seo_description":"The terms that apply when you use our website and place an order.","is_published":false,"show_in_footer":true,"sort_order":7,"created_at":"2026-10-21T13:33:34.309148+00:00","updated_at":"2026-10-21T13:33:34.309148+00:00","meta_keywords":null,"canonical_url":null,"robots_noindex":false,"og_image_url":null,"image_url":null,"image_alt":null,"is_draft_sample":true}]$QA$) on conflict do nothing;
